    private static Map<String,String> smithMetrics(){var result=new HashMap<>(Map.ofEntries(Map.entry("minecraft:iron_ingot","smelt_iron"),Map.entry("minecraft:lightning_rod","rods"),Map.entry("minecraft:iron_pickaxe","iron_pickaxe"),Map.entry("minecraft:iron_axe","iron_axe"),Map.entry("minecraft:iron_shovel","iron_shovel"),Map.entry("minecraft:iron_hoe","iron_hoe"),Map.entry("minecraft:shield","shields"),Map.entry("minecraft:gold_ingot","gold_ingots"),Map.entry("minecraft:clock","clocks"),Map.entry("minecraft:diamond_pickaxe","diamond_pickaxe"),Map.entry("minecraft:diamond_axe","diamond_axe"),Map.entry("minecraft:iron_helmet","iron_helmet"),Map.entry("minecraft:iron_chestplate","iron_chestplate"),Map.entry("minecraft:iron_leggings","iron_leggings"),Map.entry("minecraft:iron_boots","iron_boots")));result.putAll(Map.of("minecraft:nether_brick","smelt_nether_brick","minecraft:golden_boots","golden_boots","minecraft:netherite_ingot","netherite_ingot","minecraft:polished_basalt","polished_basalt","minecraft:quartz_block","quartz_block"));result.putAll(TrimCopies.metrics());return Map.copyOf(result);}
