    private static final ProfessionQuestCatalog CATALOG;
    static {
        Map<String,String> timber=new HashMap<>();for(var wood:TreeEvidence.SPECIES){timber.put("minecraft:"+wood+"_planks","planks");timber.put("minecraft:stripped_"+wood+"_log","stripped_logs");timber.put("minecraft:"+wood+"_fence","fences");timber.put("minecraft:"+wood+"_stairs","wood_stairs");timber.put("minecraft:"+wood+"_trapdoor","trapdoors");}timber.put("minecraft:charcoal","smelt_charcoal");TIMBER_METRICS=Map.copyOf(timber);
        Set<String> closure=new HashSet<>(GOALS.keySet());for(var id:GOALS.keySet()){var d=ApprovedProfessionContent.get(id);if(!(d.validation().equals(Set.of(ApprovedProfessionContent.Validation.MAKE,ApprovedProfessionContent.Validation.DEL))||(ApiaryJobs.contains(id)||id.equals(MillingService.QUEST)||id.equals(CreatePressService.QUEST))&&d.validation().equals(Set.of(ApprovedProfessionContent.Validation.JOB,ApprovedProfessionContent.Validation.DEL))||id.equals(FUEL)&&d.validation().equals(Set.of(ApprovedProfessionContent.Validation.DEL))||id.equals(ReagentCropService.QUEST)&&d.validation().equals(Set.of(ApprovedProfessionContent.Validation.GROW,ApprovedProfessionContent.Validation.DEL))||id.equals(MasterTimberDelivery.QUEST)&&d.validation().equals(Set.of(ApprovedProfessionContent.Validation.TREE,ApprovedProfessionContent.Validation.DEL)))||d.minimumTier()!=(d.profession()==Profession.MECHANIC?6:d.profession()==Profession.ENGINEER?4:d.profession()==Profession.ALCHEMIST?6:(d.profession()==Profession.MINER||d.profession()==Profession.ADVENTURER)?3:d.profession()==Profession.LIBRARIAN?4:d.profession()==Profession.BLACKSMITH?(d.rank()==ProfessionRank.APPRENTICE?3:d.rank()==ProfessionRank.JOURNEYMAN?4:5):d.rank()==ProfessionRank.APPRENTICE?2:d.rank()==ProfessionRank.JOURNEYMAN?3:6))throw new IllegalStateException("Unvalidated production family");for(var rank:ProfessionRank.values())if(rank.ordinal()<d.rank().ordinal())for(int n=1;n<=8;n++)closure.add(d.profession().questId(rank,n));}
        var queue=new ArrayDeque<>(closure);while(!queue.isEmpty())for(var prior:ApprovedProfessionContent.get(queue.removeFirst()).prerequisites())if(closure.add(prior))queue.addLast(prior);CATALOG=ProfessionQuestCatalog.approved(closure.stream().map(id->ApprovedProfessionContent.get(id).slot()).toList());
    }
    private CraftDeliveryQuests() { }
    public static Set<String> ids(){return GOALS.keySet();}
    public static boolean contains(String id){return GOALS.containsKey(id);}
    public static boolean grouped(String id){return ExpeditionSupplies.QUEST.equals(id)||CreatePressService.QUEST.equals(id)||MasterTimberDelivery.QUEST.equals(id)||TrimCopies.QUEST.equals(id)||TIMBER.equals(id)||FITTINGS.equals(id)||FUEL.equals(id);}
    public static ApprovedProfessionContent.Definition get(String id){if(!contains(id))throw new IllegalArgumentException("No validated production adapter");return ApprovedProfessionContent.get(id);}
    public static ProfessionQuestCatalog catalog(){return CATALOG;}
    public static Map<String,Integer> defaults(String id){get(id);return GOALS.get(id);}
    public static Map<String,String> metrics(Profession role){return role==Profession.MECHANIC?Map.of(MekanismSmelting.OUTPUT,MekanismSmelting.METRIC):role==Profession.ADVENTURER?ExpeditionSupplies.metrics():role==Profession.ENGINEER?engineerMetrics():role==Profession.BUILDER?METRICS:role==Profession.LUMBERJACK?TIMBER_METRICS:role==Profession.BLACKSMITH?SMITH_METRICS:role==Profession.MINER?Map.of("minecraft:stone_bricks","stone_bricks"):role==Profession.LIBRARIAN?Map.of("minecraft:book","books"):Map.of();}
    private static Map<String,String> engineerMetrics(){var map=new HashMap<>(CreateCraftQuests.METRICS);CreatePressService.OUTPUTS.values().forEach(id->map.put(id,CreatePressService.METRIC));return Map.copyOf(map);}
    public static String materialCategory(String id,String item){return ExpeditionSupplies.QUEST.equals(id)?ExpeditionSupplies.category(item):CreatePressService.QUEST.equals(id)?CreatePressService.OUTPUTS.containsValue(item)?"sheets":null:FUEL.equals(id)?Set.of("minecraft:coal","minecraft:charcoal").contains(item)?"fuel":null:TIMBER_METRICS.get(item);}
    public static Map<String,Integer> compound(CompoundTag tag){Map<String,Integer> counts=new HashMap<>();for(var key:tag.getAllKeys()){if(!tag.contains(key,Tag.TAG_INT))throw new IllegalArgumentException("Integer material count required");counts.put(key,tag.getInt(key));}return Map.copyOf(counts);}
    public static Map<String,Integer> totals(String id,Map<String,Integer> actual){
        if(ApiaryJobs.contains(id))return ApiaryInventory.totals(id,actual);if(MasterTimberDelivery.QUEST.equals(id))return Map.of("logs",MasterTimberDelivery.validate(actual));if(TrimCopies.QUEST.equals(id))return TrimCopies.totals(actual);if(!grouped(id))return Map.copyOf(actual);Map<String,Integer> result=new HashMap<>();defaults(id).keySet().forEach(k->result.put(k,0));int total=0;
        for(var e:actual.entrySet()){if(e.getValue()<1||e.getValue()>2304)throw new IllegalArgumentException("Invalid material quantity");String category=materialCategory(id,e.getKey());if(category==null||!result.containsKey(category))throw new IllegalArgumentException("Unverified material category");result.merge(category,e.getValue(),Math::addExact);total=Math.addExact(total,e.getValue());}
        if(total>2304)throw new IllegalArgumentException("Delivery exceeds inventory capacity");return Map.copyOf(result);
    }
    public static void validate(String id,CompoundTag input){
        if(ApiaryJobs.contains(id)){var totals=ApiaryInventory.totals(id,compound(input));var encoded=new CompoundTag();totals.forEach(encoded::putInt);validateGoals(id,encoded);return;}
        if(grouped(id)){if(totals(id,compound(input)).values().stream().anyMatch(n->n<1))throw new IllegalArgumentException("Every approved category must be consumed");return;}validateGoals(id,input);
    }
    public static void validateGoals(String id,CompoundTag goals){
        if(MasterTimberDelivery.QUEST.equals(id))MasterTimberDelivery.goal(goals.getInt("logs"));
        if(!goals.getAllKeys().equals(defaults(id).keySet()))throw new IllegalArgumentException("Unknown production requirement");int total=0;for(var key:goals.getAllKeys()){if(!goals.contains(key,Tag.TAG_INT)||goals.getInt(key)<1||goals.getInt(key)>2304)throw new IllegalArgumentException("Invalid bounded production quantity");total=Math.addExact(total,goals.getInt(key));}if(total>2304)throw new IllegalArgumentException("Delivery cannot fit inventory");
    }
